"""Portable protected teaching archive candidate; synthetic data only."""
import logging
import re
import secrets

from tools.teacher_content_codec import decode, MAX_BYTES

LOG = logging.getLogger(__name__)
MAGIC = b"PLTE\x01"
NONCE_BYTES = 12
TAG_BYTES = 16
MAX_PROTECTED = MAX_BYTES + len(MAGIC) + NONCE_BYTES + TAG_BYTES


def new_recovery_key():
    """256 bits generated by OS CSPRNG; never use an account password."""
    return secrets.token_hex(32)


def _key(value):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{64}", value):
        raise ValueError("Invalid recovery key format")
    return bytes.fromhex(value)


def protect(raw, recovery_key):
    try:
        # Lazy import: ordinary Teacher Studio needs no new dependency.
        # Protected operations must fail closed if the provider is absent.
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        key = _key(recovery_key)
        decode(raw)
        nonce = secrets.token_bytes(NONCE_BYTES)
        header = MAGIC + nonce
        return header + AESGCM(key).encrypt(nonce, raw, header)
    except (ImportError, ValueError, TypeError, OSError):
        LOG.warning("Protected archive creation failed")
        raise


def unprotect(raw, recovery_key):
    try:
        from cryptography.exceptions import InvalidTag
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        key = _key(recovery_key)
        if not isinstance(raw, bytes) or not len(MAGIC)+NONCE_BYTES+TAG_BYTES < len(raw) <= MAX_PROTECTED:
            raise ValueError("Invalid protected archive size")
        if not raw.startswith(MAGIC):
            raise ValueError("Invalid protected archive format")
        end = len(MAGIC) + NONCE_BYTES
        header = raw[:end]
        try:
            plaintext = AESGCM(key).decrypt(header[len(MAGIC):], raw[end:], header)
        except InvalidTag:
            raise ValueError("Wrong recovery key or damaged archive") from None
        decode(plaintext)
        return plaintext
    except (ImportError, ValueError, TypeError, OSError):
        LOG.warning("Protected archive opening failed")
        raise
